import*as THREE from'three';import{Button,Port,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{Antenna}from'./Antenna.js';import{addStickers}from'./stickers.js';const tau=Math.PI*2;
function solid(p,s,d,at,m,n){return mesh(p,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:40}),m,at,n);}function ring(p,outer,inner,d,at,m,n){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);const h=new THREE.Path();h.absarc(0,0,inner,0,tau,false);s.holes.push(h);return solid(p,s,d,at,m,n);}function axial(p,outer,inner,len,y,m,n,segments=48){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);const h=new THREE.Path();h.absarc(0,0,inner,0,tau,false);s.holes.push(h);return mesh(p,new THREE.ExtrudeGeometry(s,{depth:len,bevelEnabled:false,curveSegments:segments}).rotateX(-Math.PI/2),m,[0,y,0],n);}
function closedTube(curve,segments,radius,sides){const tube=new THREE.TubeGeometry(curve,segments,radius,sides,false),values=Array.from(tube.attributes.position.array),indices=Array.from(tube.index.array);for(const end of[0,1]){const c=curve.getPoint(end),center=values.length/3;values.push(c.x,c.y,c.z);const offset=end*segments*(sides+1),desired=curve.getTangent(end).multiplyScalar(end?1:-1);for(let i=0;i<sides;i++){const a=offset+i,b=offset+i+1,va=new THREE.Vector3().fromArray(values,a*3),vb=new THREE.Vector3().fromArray(values,b*3);if(va.sub(c).cross(vb.sub(c)).dot(desired)>0)indices.push(center,a,b);else indices.push(center,b,a);}}const g=new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(values,3));g.setIndex(indices);g.computeVertexNormals();tube.dispose();return g;}
function board(host){const s=new THREE.Shape(),e=10.2,r=3.7,a=Math.acos((e-8)/r),dy=Math.sqrt(r*r-(e-8)**2),row=-20;s.moveTo(-5.5,-30.2);s.lineTo(-8.3,-30.2);s.lineTo(-e,-28.4);s.lineTo(-e,row-dy);s.absarc(-8,row,r,Math.PI+a,Math.PI-a,false);s.lineTo(-e,26.4);s.lineTo(-8.8,28.6);s.lineTo(-3.4,28.6);s.lineTo(-3.4,25.1);s.lineTo(3.4,25.1);s.lineTo(3.4,28.6);s.lineTo(8.8,28.6);s.lineTo(e,26.4);s.lineTo(e,row+dy);s.absarc(8,row,r,a,tau-a,false);s.lineTo(e,-28.4);s.lineTo(8.3,-30.2);s.lineTo(5.5,-30.2);s.lineTo(5.5,-25.3);s.lineTo(-5.5,-25.3);s.closePath();const holes=[[0,-20,1.6],[-8,27.5,.95],[8,27.5,.95],...[-3,-1,1,3].map(x=>[x,-24.2,.48])];for(const[x,y,r]of holes){const h=new THREE.Path();h.absarc(x,y,r,0,tau,false);s.holes.push(h);}const tin=materials.metal(0xb9bdab,{roughness:.47}),green=materials.plastic(0x2c6845,{roughness:.9}),dark=materials.plastic(0x242923,{roughness:.87}),pcb=solid(host.body,s,.8,[0,0,-1.8],green,'LoRa433 own inferred populated carrier with mount reliefs,retaining/Grove bores andSMA notch');pcb.userData={role:'physical-pcb',installationInferred:true};const pads=[],barrels=[];for(const[x,y,r]of holes.slice(3)){pads.push(ring(host.body,.7,.34,.05,[x,y,-1],tin,'LoRa433 actual Grove solder annulus'));barrels.push(ring(host.body,r,.34,.8,[x,y,-1.8],tin,'LoRa433 actual Grove plated inner solder barrel'));}
 const modulePcb=slab(host.body,16,26,.6,.15,[0,-3.2,-1],materials.plastic(0x145e39,{roughness:.9}),[],.01);modulePcb.name='LoRa433 exact E220-400T22S module physical substrate,placement inferred';const contacts=[];for(const sign of[-1,1])for(let i=0;i<11;i++)contacts.push(mesh(host.body,new THREE.BoxGeometry(.65,1,.12),materials.metal(0xccb95c),[sign*7.8,-3.2+(i-5)*2,-.94],'LoRa433 E220-400T22S actual22 fixed castellated contact envelopes'));const llcc=slab(host.body,4,4,.7,.1,[0,-2,-.4],dark,[],.01);llcc.name='LoRa433 actual documented LLCC68 internal package envelope,concealed placement inferred';const shieldMaterial=materials.metal(0xacb4ad,{roughness:.63}),shield=[];for(const sign of[-1,1]){shield.push(mesh(host.body,new THREE.BoxGeometry(.25,23.4,2),shieldMaterial,[sign*7.15,-3.2,.6],'LoRa433 E220-400T22S actual RF shield side wall'));shield.push(mesh(host.body,new THREE.BoxGeometry(14.55,.25,2),shieldMaterial,[0,-3.2+sign*11.575,.6],'LoRa433 E220-400T22S actual RF shield end wall'));}shield.push(mesh(host.body,new THREE.BoxGeometry(14.55,23.4,.2),shieldMaterial,[0,-3.2,1.7],'LoRa433 E220-400T22S actual closed shield lid'));const capacitors=[];for(const[x,y,n]of[[-5.8,-18.8,'C1'],[5.8,-18.8,'C2']]){const q=slab(host.body,3.2,1.6,1.1,.08,[x,y,-1],materials.plastic(0xae9c7b),[],.01);q.name='LoRa433 own '+n+'10uF fixed capacitor';capacitors.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.4,1.6,.15),tin,[x+sign*1.4,y,-.925],'LoRa433 actual capacitor termination');}const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(6.7,8,-.1),new THREE.Vector3(7.5,15.5,0),new THREE.Vector3(5.2,23.3,0),new THREE.Vector3(0,26,0)]),coax=mesh(host.body,closedTube(curve,36,.4,10),materials.plastic(0x252a24),[0,0,0],'LoRa433 concealed physical coax appearance,route inferred not an electrical net');return{pcb,holes,pads,barrels,modulePcb,contacts,llcc,shield,capacitors,coax};}
function grove(host){const frame=new THREE.Group();frame.name='LoRa433 actual blue HY2.0-4P receiving socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const plastic=materials.plastic(spec.grove.color,{roughness:.67}),metal=materials.metal(0xb5b7a0),box=(s,p,n,m=plastic)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'LoRa433 Grove '+n),walls=[];for(const sign of[-1,1]){walls.push(box([.65,5.2,6.3],[sign*4.675,0,-3.15],'actual side wall'));box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'actual guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'actual latch shoulder');}const floor=box([8.7,.65,6.3],[0,-2.275,-3.15],'actual floor'),rear=box([8.7,4.55,.65],[0,.325,-5.975],'actual closed dielectric rear'),bridge=box([4.8,.45,2.3],[0,2.375,-4.5],'actual retaining bridge'),contacts=[],tails=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],'actual recessed contact'+(i+1),metal));const t=new THREE.Group();t.name='LoRa433 Grove actual bent solder tail'+(i+1);frame.add(t);mesh(t,new THREE.BoxGeometry(.42,.42,2),metal,[(i-1.5)*2,.2,-6.7],'LoRa433 Grove actual rearward solder segment');mesh(t,new THREE.BoxGeometry(.42,3.6,.42),metal,[(i-1.5)*2,-1.5,-7.7],'LoRa433 Grove actual plated-through solder leg');tails.push(t);}const port=host.add(new Port({id:'grove',label:'PORT.C UART · physical labels only',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:['GND','5V','RXD','TXD'].map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:2,center:[0,.2],order:col=>4-col},meta:{role:'visual-connector',face:'bottom',scope:'Four real contacts,cable attachment and documentary labels only.No UART packets,RF,electrical ormode behavior'}}));return{frame,walls,floor,rear,bridge,contacts,tails,port};}
function sma(host){const frame=new THREE.Group();frame.name='LoRa433 actual SMA female receiving assembly';host.body.add(frame);const gold=materials.metal(0xd0b947,{roughness:.42}),white=materials.plastic(0xe9e8d8,{roughness:.8});const base=mesh(frame,new THREE.CylinderGeometry(3.8,3.8,2.5,6),gold,[0,28,0],'LoRa433 actual captured hex fixing visible through native two windows'),barrel=axial(frame,3.05,2.1,7.4,32,gold,'LoRa433 actual hollow SMA outer receiving barrel'),rear=axial(frame,2.5,.65,7.2,24.8,gold,'LoRa433 SMA actual deep bored rear carrier'),dielectric=axial(frame,2.07,.65,1.2,37.8,white,'LoRa433 SMA actual bored dielectric face'),contact=axial(frame,.63,.32,3.1,36,gold,'LoRa433 SMA actual female centre-contact socket'),floor=mesh(frame,new THREE.CylinderGeometry(.32,.32,.12,32),gold,[0,35.94,0],'LoRa433 SMA actual blind centre-contact floor'),threads=[];for(let i=0;i<10;i++)threads.push(mesh(frame,new THREE.TorusGeometry(3.1,.12,8,48).rotateX(Math.PI/2),gold,[0,32.5+i*.65,0],'LoRa433 SMA actual fixed external thread crest'));const port=host.add(new Port({id:'sma',label:'SMA female · physical antenna interface',connector:'sma-female',position:spec.sma.position,hitSize:[7,1,7],meta:{role:'visual-connector',face:'top',physicalConnector:'sma-female',scope:'Actual coax mating appearance only.NoRF,frequency,range,gain,electrical orprotocol behavior'}}));return{frame,base,barrel,rear,dielectric,contact,floor,threads,port};}
function controls(host,positions){const dark=materials.plastic(0x20251f,{roughness:.85}),tin=materials.metal(0xb7b9aa),cream=materials.plastic(0xe6e2ca,{roughness:.72}),v=spec.dip,base=slab(host.body,...v.body.size,.12,v.body.position,dark,[],.01);base.name='LoRa433 S1 actual fixed DIP2 body';const holes=v.positions.map(p=>({w:1.15,h:3.05,r:.08,cx:p[0]+4.15,cy:0})),cover=slab(host.body,...v.cover.size,.12,v.cover.position,dark,holes,0);cover.name='LoRa433 S1 fixed real two-slot DIP cover';const terminals=[];for(const side of[-1,1])for(const[x]of v.positions)terminals.push(mesh(host.body,new THREE.BoxGeometry(.55,.7,.15),tin,[x,16.1+side*3.15,-.925],'LoRa433 S1 actual fixed DIP solder terminal'));const sliders=v.positions.map((p,i)=>{const cap=slab(new THREE.Group(),.85,1.1,.5,.05,[0,0,0],cream,[],.005);cap.name='LoRa433 S1 actual retained moving slider'+(i+1);const c=host.add(new Button({id:'m'+i,label:'S1.'+(i+1)+' stable physical detent',mesh:cap,position:p,axis:v.axis,travel:v.travelMm,latching:true,longPressMs:0,meta:{role:'visual-control',mechanism:'retained stable DIP slide',detents:[0,1],travelSource:'Exact own433 visible white DIP and source opening;1.1mm throw/installation inferred',scope:'Actual independent thumb/input intent only.Cancel/release preserves selected stable detent.No mode mapping,RF,UART,electrical orfirmware behavior'}}));c.setPosition(positions[i],{immediate:true});return c;});return{base,cover,terminals,sliders,fixed:[base,cover,...terminals]};}
function fixing(host){const metal=materials.metal(0xb5bdb2),items=[];for(const[x,y]of[[-8,27.5],[8,27.5],[0,-20]]){const s=new THREE.Shape();s.absarc(0,0,1.5,0,tau,false);const h=new THREE.Path();for(let i=0;i<6;i++){const a=-i*tau/6; i?h.lineTo(.6*Math.cos(a),.6*Math.sin(a)):h.moveTo(.6*Math.cos(a),.6*Math.sin(a));}h.closePath();s.holes.push(h);const head=solid(host.body,s,.4,[x,y,-3.98],metal,'LoRa433 actual fixed rear hex retaining head'),floor=mesh(host.body,new THREE.CylinderGeometry(.61,.61,.1,6).rotateX(Math.PI/2),metal,[x,y,-3.53],'LoRa433 actual blind retaining hex floor'),shank=mesh(host.body,new THREE.CylinderGeometry(.6,.6,5.2,32).rotateX(Math.PI/2),metal,[x,y,-.9],'LoRa433 actual fixed retaining shank');items.push({head,floor,shank});}return items;}
export function buildLoRa433(host,{antenna=false,m0Position=0,m1Position=0}={}){if(typeof antenna!=='boolean')throw new TypeError('antenna must be boolean');for(const p of[m0Position,m1Position])if(p!==0&&p!==1)throw new RangeError('DIP visual positions must be0 or1');const parts=addCadParts(host,data,{shell:materials.plastic(0x555b54,{roughness:.84})}),pcb=board(host),input=grove(host),output=sma(host),actuators=controls(host,[m0Position,m1Position]),screws=fixing(host),labels={};for(const face of['front','back']){const v=spec.labels[face],p=slab(host.body,...v.size,.04,.8,v.position,materials.plastic(0xd7dcd4,{roughness:.88}),face==='front'?[v.hole]:[],0);p.name='LoRa433 actual '+face+' adhesive film';p.userData={role:'physical-label-substrate',face};labels[face]=p;}host.lora433Assembly={parts,pcb,input,sma:output,controls:actuators,screws,labels};host.unitStickers=addStickers(host);if(antenna)output.port.attach(new Antenna());}
